INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-6', 'desert-motors-insights-6', 'Desert Motors Industry Brief #6: 5-Year Ceramic Paint Protection', 'تقرير محركات الصحراء التخصصي #6: حماية سيراميك للطلاء 5 سنوات', 'Key operational benchmarks and best practices from Desert Motors in Salmabad.', 'أبرز المعايير التشغيلية وأفضل الممارسات من محركات الصحراء في Salmabad.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Authorized 4x4 service center and spare parts distributor specializing in off-road suspension, ceramic detailing, and OEM parts. Our 5-Year Ceramic Paint Protection division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مركز خدمة معتمد لسيارات الدفع الرباعي وموزع قطع غيار أصلية وتجهيزات الرحلات. يساعد قسم حماية سيراميك للطلاء 5 سنوات المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>Authorized 4x4 service center and spare parts distributor specializing in off-road suspension, ceramic detailing, and OEM parts.</p><p>Our 5-Year Ceramic Paint Protection division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>مركز خدمة معتمد لسيارات الدفع الرباعي وموزع قطع غيار أصلية وتجهيزات الرحلات.</p><p>يساعد قسم حماية سيراميك للطلاء 5 سنوات المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'automotive', '{"automotive","Salmabad","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '54 days', false, now() - interval '54 days', now()) ON CONFLICT (id) DO NOTHING;
